import logging
from db.pg_conn import get_conn

logging.basicConfig(level=logging.INFO)
log = logging.getLogger("pg_init")

DROP_ORDER = ["raw_trades", "iv_history", "setup_cache", "inflection_cache"]

SCHEMA = [
    "CREATE TABLE IF NOT EXISTS raw_trades (id serial primary key, ticker text, price numeric)",
    "CREATE TABLE IF NOT EXISTS iv_history (id serial primary key, ticker text, iv numeric)",
    "CREATE TABLE IF NOT EXISTS setup_cache (id serial primary key, ticker text, direction text)",
    "CREATE TABLE IF NOT EXISTS inflection_cache (id serial primary key, ticker text)",
    "ALTER TABLE setup_cache ADD COLUMN IF NOT EXISTS signal_tier text",
    "ALTER TABLE setup_cache ADD COLUMN IF NOT EXISTS secondary_direction text",
]

def init_db(drop_existing: bool = False, skip_indexes: bool = False):
    conn = get_conn()
    if drop_existing:
        log.info("drop_existing=True - dropping all tables")
        for t in DROP_ORDER:
            conn.execute(f"DROP TABLE IF EXISTS {t} CASCADE")
    for stmt in SCHEMA:
        conn.execute(stmt)
    conn.commit()
PYEOF
