package dal

import "database/sql"

type Database struct {
    DB *sql.DB
}

type Character struct {
    ID   int
    Name string
}

func (d *Database) GetCharacters(gameID int) ([]Character, error) {
    rows, err := d.DB.Query(`SELECT characterid, name FROM character WHERE gameid = ?`, gameID)
    if err != nil {
        return nil, err
    }
    defer rows.Close()
    var chars []Character
    for rows.Next() {
        var c Character
        if err := rows.Scan(&c.ID, &c.Name); err != nil {
            return nil, err
        }
        chars = append(chars, c)
    }
    return chars, rows.Err()
}
