const POSITIONS = ['GS', 'GA', 'WA', 'C', 'WD', 'GD', 'GK'];

export default function App() {
  const [screen, setScreen] = useState('setup');
  const [events, setEvents] = useState([]);
  return <div className='app'>{screen === 'setup' ? <button onClick={() => setScreen('court')}>Start</button> : <p>{events.length} events</p>}</div>;
}

// ===== REPORT GENERATION (core feature, ~2000 lines in the real file) =====
function buildShootingTable(events) {
  const shots = events.filter(e => e.type === 'shot');
  const goals = shots.filter(e => e.result === 'goal').length;
  return `<table class='shooting'><tr><th>Attempts</th><th>Goals</th><th>%</th></tr><tr><td>${shots.length}</td><td>${goals}</td><td>${shots.length ? Math.round(goals / shots.length * 100) : 0}</td></tr></table>`;
}

function buildCentrePassConversionTable(events) {
  const cps = events.filter(e => e.type === 'centre_pass');
  const converted = cps.filter(e => e.converted).length;
  return `<section class='cpc'><h2>Centre Pass Conversion</h2><p>${converted}/${cps.length}</p></section>`;
}

function buildQuarterBreakdown(events) {
  return [1, 2, 3, 4].map(q => `<h3>Q${q}</h3><p>${events.filter(e => e.quarter === q).length} events</p>`).join('');
}

function buildPlayerRatings(events, players) {
  return players.map(p => `<tr><td>${p.name}</td><td>${events.filter(e => e.playerId === p.id).length}</td></tr>`).join('');
}

export function generateFullReportHTML(match, events, players) {
  return `<html><body><h1>${match.home} v ${match.away}</h1>${buildShootingTable(events)}${buildCentrePassConversionTable(events)}${buildQuarterBreakdown(events)}<table class='ratings'>${buildPlayerRatings(events, players)}</table></body></html>`;
}
