import json
from pathlib import Path

DATA_DIR = Path.home() / '.ledger'


def load_entries(name):
    path = DATA_DIR / (name + '.json')
    if not path.exists():
        return []
    return json.loads(path.read_text())


def save_entries(name, entries):
    DATA_DIR.mkdir(parents=True, exist_ok=True)
    (DATA_DIR / (name + '.json')).write_text(json.dumps(entries, indent=2))


def add_entry(name, amount, memo):
    entries = load_entries(name)
    entries.append({'amount': amount, 'memo': memo})
    save_entries(name, entries)
    return entries


def balance(name):
    return sum(e['amount'] for e in load_entries(name))


def reconcile(name, statement):
    ledger = {(e['amount'], e['memo']) for e in load_entries(name)}
    return [s for s in statement if (s['amount'], s['memo']) not in ledger]


def export_report(name, out_path):
    entries = load_entries(name)
    lines = ['%s: %.2f' % (e['memo'], e['amount']) for e in entries]
    lines.append('TOTAL: %.2f' % balance(name))
    Path(out_path).write_text('\n'.join(lines) + '\n')
