// transcriber.js - audio transcription pipeline
const fs = require('fs');

async function transcribeAudio(client, filePath, opts = {}) {
  const audio = fs.readFileSync(filePath);
  const response = await client.transcribe({
    audio: audio.toString('base64'),
    language: opts.language || 'en-US',
    diarization: true,
  });
  const segments = normalizeSegments(response.segments);
  return mergeSpeakerTurns(segments);
}

function normalizeSegments(segments) {
  return segments
    .filter((s) => s.text && s.text.trim().length > 0)
    .map((s) => ({
      speaker: s.speakerTag || 0,
      start: Number(s.startTime),
      end: Number(s.endTime),
      text: s.text.trim(),
    }));
}

function mergeSpeakerTurns(segments) {
  const turns = [];
  for (const seg of segments) {
    const last = turns[turns.length - 1];
    if (last && last.speaker === seg.speaker && seg.start - last.end < 1.5) {
      last.text += ' ' + seg.text;
      last.end = seg.end;
    } else {
      turns.push({ ...seg });
    }
  }
  return turns;
}

module.exports = { transcribeAudio, normalizeSegments, mergeSpeakerTurns };
EOF
