import { WheelEditor } from "./editor/WheelEditor";
import { RulesEditor } from "./editor/RulesEditor";
import { PresetManager } from "./editor/PresetManager";
import { DualWheelEngine } from "./engine/DualWheelEngine";
import { GameConfig, loadDefaultConfiguration } from "./config/GameConfig";

type AppMode = "play" | "wheel-editor" | "rules-editor" | "presets";

export class MainApplication {
  private engine: DualWheelEngine;
  private wheelEditor: WheelEditor;
  private rulesEditor: RulesEditor;
  private presetManager: PresetManager;
  private config: GameConfig;
  private mode: AppMode = "play";
  private rafId = 0;

  constructor(private root: HTMLElement) {
    this.config = loadDefaultConfiguration();
    this.engine = new DualWheelEngine(this.config.wheels);
    this.wheelEditor = new WheelEditor(this.config, () => this.applyConfig());
    this.rulesEditor = new RulesEditor(this.config.rules);
    this.presetManager = new PresetManager(this.config);
  }

  init(): void {
    this.setMode("play");
    this.startRenderLoop();
  }

  setMode(mode: AppMode): void {
    this.mode = mode;
    this.root.innerHTML = "";
    if (mode === "wheel-editor") this.wheelEditor.mount(this.root);
    else if (mode === "rules-editor") this.rulesEditor.mount(this.root);
    else if (mode === "presets") this.presetManager.mount(this.root);
    else this.engine.mount(this.root);
  }

  private applyConfig(): void {
    this.engine.reconfigure(this.config.wheels, this.config.rules);
  }

  private startRenderLoop(): void {
    const tick = (t: number) => { this.engine.step(t); this.rafId = requestAnimationFrame(tick); };
    this.rafId = requestAnimationFrame(tick);
  }

  stopRenderLoop(): void {
    cancelAnimationFrame(this.rafId);
  }
}
